<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\SchoolFees;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Carbon\CarbonImmutable;
class FeesController extends Controller
{
 private const MONEY=['required','regex:/^\d{1,8}(\.\d{1,2})?$/D'];
 public function __construct(private SchoolFees $fees){}
 private function date():string{return now('Asia/Karachi')->toDateString();}
 private function campus(array $campuses,?int $id):void{if($id!==null)abort_unless(in_array($id,$campuses,true),404);}
 private function globalWrite(int $sid,array $campuses):void{abort_if(DB::table('campuses')->where('school_id',$sid)->whereNotIn('id',$campuses)->exists(),403,'All campus access is required for school-wide fee setup.');}
 private function visibleEnrollments(int $sid,array $campuses){return DB::table('enrollments as e')->join('sections as s','s.id','=','e.section_id')->join('students as st','st.id','=','e.student_id')->where('e.school_id',$sid)->whereIn('s.campus_id',$campuses);}
 public function setup(Request $r){[$sid,$campuses]=$this->fees->context($r);$plans=DB::table('fee_plans')->where('school_id',$sid)->where(fn($q)=>$q->whereNull('campus_id')->orWhereIn('campus_id',$campuses))->orderByDesc('id')->get();foreach($plans as $p)$p->locked=DB::table('student_fee_assignments')->where('school_id',$sid)->where('fee_plan_id',$p->id)->exists();return response()->json(['permissions'=>array_values(array_filter(['fees.manage','fees.collect','fees.request_reversal','fees.approve_concession','fees.approve_reversal'],fn($p)=>$this->fees->access->can($r,$p))),'heads'=>DB::table('fee_heads')->where('school_id',$sid)->orderBy('name')->get(),'plans'=>$plans,'items'=>DB::table('fee_plan_items')->where('school_id',$sid)->whereIn('fee_plan_id',$plans->pluck('id'))->get(),'accounts'=>DB::table('bank_accounts')->where('school_id',$sid)->where(fn($q)=>$q->whereNull('campus_id')->orWhereIn('campus_id',$campuses))->get(['id','name','campus_id','account_reference']),'campuses'=>DB::table('campuses')->where('school_id',$sid)->whereIn('id',$campuses)->get(['id','name','status']),'sessions'=>DB::table('academic_sessions')->where('school_id',$sid)->get(),'classes'=>DB::table('classes')->where('school_id',$sid)->orderBy('position')->get(),'sections'=>DB::table('sections as s')->join('classes as c','c.id','=','s.class_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->join('campuses as p','p.id','=','s.campus_id')->where('s.school_id',$sid)->whereIn('s.campus_id',$campuses)->get(['s.*','c.name as class_name','y.name as session_name','p.name as campus_name'])]);}
 public function enrollments(Request $r){[$sid,$campuses]=$this->fees->context($r);$d=$r->validate(['search'=>'nullable|string|max:100','page'=>'nullable|integer|min:1']);$q=$this->visibleEnrollments($sid,$campuses);if(!empty($d['search']))$q->where(fn($q)=>$q->where('st.admission_no','like','%'.$d['search'].'%')->orWhereRaw("CONCAT_WS(' ',st.first_name,st.last_name) LIKE ?",['%'.$d['search'].'%']));return response()->json($q->join('classes as c','c.id','=','s.class_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->orderByDesc('e.starts_on')->orderByDesc('e.id')->paginate(25,['e.*','st.admission_no','st.first_name','st.last_name','s.campus_id','s.name as section_name','c.name as class_name','y.name as session_name']));}
 public function saveHead(Request $r,?int $id=null){$d=$r->validate(['name'=>'required|string|min:2|max:160','code'=>'required|alpha_dash|max:30']);$saved=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d,$id){$this->globalWrite($sid,$campuses);if($id)$this->fees->row('fee_heads',$sid,$id);if(DB::table('fee_heads')->where('school_id',$sid)->where('code',$d['code'])->when($id,fn($q)=>$q->where('id','<>',$id))->exists())$this->fees->fail('Fee head code is already used.');if($id)DB::table('fee_heads')->where('school_id',$sid)->where('id',$id)->update($d+['updated_at'=>now()]);else $id=DB::table('fee_heads')->insertGetId($d+['school_id'=>$sid,'created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.head_saved','fee_heads',$id,$d);return $id;});return response()->json(['id'=>$saved,'message'=>'Fee head saved.']);}
 public function account(Request $r){$d=$r->validate(['name'=>'required|string|min:2|max:160','account_reference'=>'required|string|max:160','campus_id'=>'nullable|integer']);$id=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d){$this->campus($campuses,$d['campus_id']??null);if(empty($d['campus_id']))$this->globalWrite($sid,$campuses);$id=DB::table('bank_accounts')->insertGetId($d+['school_id'=>$sid,'opening_balance'=>'0.00','created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.account_added','bank_accounts',$id,['name'=>$d['name']]);return $id;});return response()->json(['id'=>$id,'message'=>'Collection account added.']);}
 public function plan(Request $r,?int $id=null){$d=$r->validate(['name'=>'required|string|min:2|max:160','academic_session_id'=>'required|integer','class_id'=>'required|integer','campus_id'=>'nullable|integer','starts_on'=>'required|date_format:Y-m-d','ends_on'=>'nullable|date_format:Y-m-d|after_or_equal:starts_on','items'=>'required|array|min:1|max:30','items.*.fee_head_id'=>'required|integer|distinct','items.*.amount'=>self::MONEY,'items.*.frequency'=>['required',Rule::in(['monthly','annual','once'])]]);
  $saved=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d,$id){$this->campus($campuses,$d['campus_id']??null);if(empty($d['campus_id']))$this->globalWrite($sid,$campuses);$session=$this->fees->row('academic_sessions',$sid,$d['academic_session_id']);$this->fees->row('classes',$sid,$d['class_id']);if($session->status!=='active'||$d['starts_on']<$session->starts_on||($d['ends_on']??$session->ends_on)>$session->ends_on)$this->fees->fail('Plan dates must stay inside an active academic session.');
   if($id){$old=$this->fees->row('fee_plans',$sid,$id);$this->campus($campuses,$old->campus_id);if($old->campus_id===null)$this->globalWrite($sid,$campuses);if(DB::table('student_fee_assignments')->where('school_id',$sid)->where('fee_plan_id',$id)->exists())$this->fees->fail('Assigned fee plans are locked. Create a new plan for revised rates.');}
   foreach($d['items'] as $line)$this->fees->row('fee_heads',$sid,$line['fee_head_id']);$header=array_diff_key($d,['items'=>true]);if($id){DB::table('fee_plan_items')->where('school_id',$sid)->where('fee_plan_id',$id)->delete();DB::table('fee_plans')->where('school_id',$sid)->where('id',$id)->update($header+['updated_at'=>now()]);}else $id=DB::table('fee_plans')->insertGetId($header+['school_id'=>$sid,'created_at'=>now(),'updated_at'=>now()]);foreach($d['items'] as $line)DB::table('fee_plan_items')->insert($line+['school_id'=>$sid,'fee_plan_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.plan_saved','fee_plans',$id,['name'=>$d['name'],'items'=>$d['items']]);return $id;});return response()->json(['id'=>$saved,'message'=>'Fee plan saved.']);}
 public function assignment(Request $r){$d=$r->validate(['fee_plan_id'=>'required|integer','enrollment_id'=>'required_without:section_id|nullable|integer','section_id'=>'required_without:enrollment_id|nullable|integer','starts_on'=>'required|date_format:Y-m-d','reason'=>'required|string|min:5|max:1000']);$count=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d){$plan=$this->fees->row('fee_plans',$sid,$d['fee_plan_id']);$this->campus($campuses,$plan->campus_id);$ids=!empty($d['enrollment_id'])?[$d['enrollment_id']]:$this->visibleEnrollments($sid,$campuses)->where('e.section_id',$d['section_id'])->where('e.starts_on','<=',$d['starts_on'])->where(fn($q)=>$q->whereNull('e.ends_on')->orWhere('e.ends_on','>=',$d['starts_on']))->pluck('e.id')->all();if(!$ids)$this->fees->fail('No enrollments cover the assignment date.');$count=0;
   foreach($ids as $id){$e=$this->fees->enrollment($sid,$campuses,$id);if($plan->class_id!=$e->class_id||$plan->academic_session_id!=$e->academic_session_id||($plan->campus_id!==null&&$plan->campus_id!=$e->campus_id))$this->fees->fail('Fee plan class, campus and session must match every selected enrollment.');$end=min($plan->ends_on??$e->session_end,$e->ends_on??$e->session_end,$e->session_end);if($d['starts_on']<max($e->starts_on,$plan->starts_on)||$d['starts_on']>$end)$this->fees->fail('Assignment dates must stay inside the plan and enrollment.');
    $same=DB::table('student_fee_assignments')->where('school_id',$sid)->where('enrollment_id',$id)->where('starts_on',$d['starts_on'])->first();if($same){if($same->fee_plan_id==$plan->id)continue;$this->fees->fail('An assignment already begins on this date.');}
    if(DB::table('invoices')->where('school_id',$sid)->where('enrollment_id',$id)->where('kind','monthly')->where('status','<>','void')->where('period','>=',CarbonImmutable::parse($d['starts_on'])->startOfMonth()->toDateString())->exists())$this->fees->fail('Issued billing protects this assignment period. Choose a later unbilled month.');
    $overlap=DB::table('student_fee_assignments')->where('school_id',$sid)->where('enrollment_id',$id)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$d['starts_on']))->get();foreach($overlap as $old){if($old->starts_on>=$d['starts_on'])$this->fees->fail('A future assignment overlaps this change.');DB::table('student_fee_assignments')->where('school_id',$sid)->where('id',$old->id)->update(['ends_on'=>CarbonImmutable::parse($d['starts_on'])->subDay()->toDateString(),'updated_at'=>now()]);}
    $aid=DB::table('student_fee_assignments')->insertGetId(['school_id'=>$sid,'enrollment_id'=>$id,'fee_plan_id'=>$plan->id,'assigned_by'=>$this->fees->access->membership($r)->id,'starts_on'=>$d['starts_on'],'ends_on'=>$end,'reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.plan_assigned','student_fee_assignments',$aid,['enrollment_id'=>$id,'fee_plan_id'=>$plan->id,'reason'=>$d['reason']]);$count++;
   }return $count;});return response()->json(['message'=>$count.' fee assignments saved.','count'=>$count]);}
 public function student(Request $r,int $enrollment){[$sid,$campuses]=$this->fees->context($r);$e=$this->fees->enrollment($sid,$campuses,$enrollment);return response()->json(['enrollment'=>$e,'assignments'=>DB::table('student_fee_assignments as a')->join('fee_plans as p','p.id','=','a.fee_plan_id')->where('a.school_id',$sid)->where('a.enrollment_id',$enrollment)->orderByDesc('a.starts_on')->get(['a.*','p.name as plan_name']),'concessions'=>DB::table('student_concessions as c')->join('fee_heads as h','h.id','=','c.fee_head_id')->where('c.school_id',$sid)->where('c.enrollment_id',$enrollment)->orderByDesc('c.starts_on')->get(['c.*','h.name as head_name'])]);}
 public function concession(Request $r){$d=$r->validate(['enrollment_id'=>'required|integer','fee_head_id'=>'required|integer','kind'=>['required',Rule::in(['fixed','percent'])],'value'=>self::MONEY,'starts_on'=>'required|date_format:Y-m-d','ends_on'=>'required|date_format:Y-m-d|after_or_equal:starts_on','reason'=>'required|string|min:5|max:1000']);$id=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d){$e=$this->fees->enrollment($sid,$campuses,$d['enrollment_id']);$this->fees->row('fee_heads',$sid,$d['fee_head_id']);if(($d['kind']==='percent'&&SchoolFees::cents($d['value'])>10000)||$d['starts_on']<$e->starts_on||$d['ends_on']>min($e->ends_on??$e->session_end,$e->session_end))$this->fees->fail('Check discount amount and enrollment dates.');$id=DB::table('student_concessions')->insertGetId($d+['school_id'=>$sid,'created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.concession_requested','student_concessions',$id,['reason'=>$d['reason']]);return $id;});return response()->json(['id'=>$id,'message'=>'Concession recorded; approval required before billing.']);}
 public function approveConcession(Request $r,int $concession){$this->fees->lock($r,'fees.approve_concession',function($sid,$campuses)use($r,$concession){$c=$this->fees->row('student_concessions',$sid,$concession);$this->fees->enrollment($sid,$campuses,$c->enrollment_id);if($c->approved_by)return;if(DB::table('student_concessions')->where('school_id',$sid)->where('enrollment_id',$c->enrollment_id)->where('fee_head_id',$c->fee_head_id)->where('id','<>',$c->id)->whereNotNull('approved_by')->where('starts_on','<=',$c->ends_on)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$c->starts_on))->exists())$this->fees->fail('An approved concession already covers this fee head and date range.');DB::table('student_concessions')->where('school_id',$sid)->where('id',$concession)->update(['approved_by'=>$this->fees->access->membership($r)->id,'updated_at'=>now()]);$this->fees->access->audit($r,'fees.concession_approved','student_concessions',$concession);});return response()->json(['message'=>'Concession approved. Existing invoice amounts stay unchanged.']);}
 private function billingData(Request $r):array{return $r->validate(['month'=>'required|date_format:Y-m','issued_on'=>'required|date_format:Y-m-d|before_or_equal:'.$this->date(),'due_on'=>'required|date_format:Y-m-d|after_or_equal:issued_on','campus_id'=>'nullable|integer','section_id'=>'nullable|integer','student_id'=>'nullable|integer']);}
 public function preview(Request $r){[$sid,$campuses]=$this->fees->context($r,'fees.manage');$d=$this->billingData($r);return response()->json(['rows'=>$this->fees->generateRows($sid,$campuses,$d)]);}
 public function generate(Request $r){$d=$this->billingData($r);$result=$this->fees->lock($r,'fees.manage',fn($sid,$campuses)=>$this->fees->issue($r,$sid,$campuses,$d));return response()->json($result+['message'=>$result['issued'].' invoices generated; '.$result['skipped'].' already billed.']);}
 public function opening(Request $r){$d=$r->validate(['enrollment_id'=>'required|integer','amount'=>self::MONEY,'issued_on'=>'required|date_format:Y-m-d|before_or_equal:'.$this->date(),'due_on'=>'required|date_format:Y-m-d|after_or_equal:issued_on','reason'=>'required|string|min:5|max:1000']);$id=$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d){$e=$this->fees->enrollment($sid,$campuses,$d['enrollment_id']);if(SchoolFees::cents($d['amount'])<=0)$this->fees->fail('Opening dues must be greater than zero.');if(DB::table('invoices as i')->join('enrollments as en','en.id','=','i.enrollment_id')->where('i.school_id',$sid)->where('en.student_id',$e->student_id)->where('i.status','<>','void')->exists())$this->fees->fail('Opening dues must be entered before this student has issued invoices.');$id=DB::table('invoices')->insertGetId(['school_id'=>$sid,'enrollment_id'=>$e->id,'number'=>$this->fees->number('INV',$sid,'invoices'),'period'=>CarbonImmutable::parse($d['issued_on'])->startOfMonth()->toDateString(),'kind'=>'opening_dues','installment_no'=>(int)DB::table('invoices')->where('school_id',$sid)->where('enrollment_id',$e->id)->where('kind','opening_dues')->max('installment_no')+1,'issued_on'=>$d['issued_on'],'due_on'=>$d['due_on'],'status'=>'unpaid','total'=>$d['amount'],'created_at'=>now(),'updated_at'=>now()]);DB::table('invoice_items')->insert(['school_id'=>$sid,'invoice_id'=>$id,'description'=>'Opening dues · '.mb_substr($d['reason'],0,130),'quantity'=>'1.00','unit_amount'=>$d['amount'],'discount_amount'=>'0.00','line_total'=>$d['amount'],'billing_frequency'=>'opening','created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.opening_dues','invoices',$id,['reason'=>$d['reason'],'amount'=>$d['amount']]);return $id;});return response()->json(['id'=>$id,'message'=>'Opening dues recorded.']);}
 public function void(Request $r,int $invoice){$d=$r->validate(['reason'=>'required|string|min:5|max:1000']);$this->fees->lock($r,'fees.manage',function($sid,$campuses)use($r,$d,$invoice){$i=$this->fees->invoice($sid,$campuses,$invoice);if($i->status==='void')return;if($this->fees->paid($sid,$invoice)>0)$this->fees->fail('Reverse or refund allocated payments before voiding this invoice.');DB::table('invoices')->where('school_id',$sid)->where('id',$invoice)->update(['status'=>'void','void_reason'=>$d['reason'],'updated_at'=>now()]);$this->fees->access->audit($r,'fees.invoice_voided','invoices',$invoice,$d);});return response()->json(['message'=>'Invoice voided; history retained.']);}
}
